import{_ as e,o as l,c as o,a5 as t}from"./chunks/framework.a5no_H3L.js";const b=JSON.parse('{"title":"博客上线","description":"The Stack 博客上线，记录 Java 后端的技术原理、工程实践与踩坑经验。","frontmatter":{"title":"博客上线","date":"2026-11-04T00:00:00.000Z","author":"b1tzer","category":"Java","description":"The Stack 博客上线，记录 Java 后端的技术原理、工程实践与踩坑经验。","tags":["站点","公告"],"blog":"post","aside":"left","sidebar":false,"prev":false,"next":false},"headers":[],"relativePath":"blog/posts/2026-11-04-hello-blog.md","filePath":"blog/posts/2026-11-04-hello-blog.md"}'),s={name:"blog/posts/2026-11-04-hello-blog.md"};function r(d,a,i,c,n,p){return l(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="博客上线" tabindex="-1" data-src-line="2" data-src-file="blog/posts/2026-11-04-hello-blog.md">博客上线 <a class="header-anchor" href="#博客上线" aria-label="Permalink to &quot;博客上线&quot;">​</a></h1><p data-src-line="4" data-src-file="blog/posts/2026-11-04-hello-blog.md">知识库按模块组织成体系，但有些内容天然不属于某个专题：一次排查线上问题的完整过程、一段源码阅读的散记、一个反复被问到的面试点。它们单独成篇太薄，塞进某个专题又显突兀。</p><p data-src-line="6" data-src-file="blog/posts/2026-11-04-hello-blog.md">博客就是给这些内容留的位置。</p><h2 id="写什么" tabindex="-1" data-src-line="8" data-src-file="blog/posts/2026-11-04-hello-blog.md">写什么 <a class="header-anchor" href="#写什么" aria-label="Permalink to &quot;写什么&quot;">​</a></h2><p data-src-line="10" data-src-file="blog/posts/2026-11-04-hello-blog.md">这里会记录两类内容。一类是知识库里不便展开的长过程，比如一次从日志到根因的完整排查；另一类是还没沉淀成体系、但值得先记下来的零散判断。前者是完整复盘，后者是待打磨的素材，等积累够了再回填进对应专题。</p><h2 id="怎么看" tabindex="-1" data-src-line="12" data-src-file="blog/posts/2026-11-04-hello-blog.md">怎么看 <a class="header-anchor" href="#怎么看" aria-label="Permalink to &quot;怎么看&quot;">​</a></h2><p data-src-line="14" data-src-file="blog/posts/2026-11-04-hello-blog.md">列表页按时间倒序排列，每篇文章带一句话摘要和标签。文章本身沿用知识库默认的排版，有目录、有编辑入口，和专题页面保持一致。</p>',7)])])}const g=e(s,[["render",r]]);export{b as __pageData,g as default};
